/**
 * Which verbs of "Top 10 verbs" parts 1-3 can be practised in each language, and which are
 * still missing (no entry, or only an auto-generated placeholder).
 *   npm run report:top-verbs            -> Markdown on stdout
 */
const fs = require('fs'), path = require('path');
const T = require('../shared/js/top_verbs_preset.js');
const root = path.join(__dirname, '..');
const CONCEPTS = T.PART_CONCEPTS;
const LANGS = ['en', 'fr', 'es', 'it', 'de', 'pt', 'ru', 'el', 'tt', 'ba', 'cv', 'br', 'hy', 'ka'];

const out = ['# Top 10 verbs: practice coverage', '',
  'Generated by `npm run report:top-verbs`. A verb counts as available when its data entry exists, is not an',
  'auto-generated placeholder and has a present tense.', ''];
const summary = [];
const details = [];
for (const lang of LANGS) {
  const cfg = T.getConfig(lang);
  const db = JSON.parse(fs.readFileSync(path.join(root, cfg.toolPath, 'data/verbs.json'), 'utf8'));
  const row = [lang];
  for (const part of [1, 2, 3]) {
    const r = T.resolvePart(lang, db, part);
    const groupsOk = r.groups.filter(g => g.length).length;
    row.push(`${r.lemmas.length} verbs, ${groupsOk}/10 groups`);
    if (part === 1) continue;
    const explicit = T.PART_LEMMAS[lang] && T.PART_LEMMAS[lang][part];
    const missing = [];
    r.groups.forEach((found, i) => {
      const wanted = explicit ? explicit[i] : CONCEPTS[part][i];
      const gap = explicit ? wanted.filter(v => !found.includes(v)) : [];
      const label = CONCEPTS[part][i].join(' / ');
      if (!found.length) missing.push(`- group ${i + 1} (${label}): **nothing yet**${gap.length ? ' — wanted: ' + gap.join(', ') : ''}`);
      else if (gap.length) missing.push(`- group ${i + 1} (${label}): have ${found.join(', ')}; missing ${gap.join(', ')}`);
    });
    if (missing.length) details.push(`### ${lang} — part ${part}`, '', ...missing, '');
  }
  summary.push(row);
}
out.push('| language | part 1 | part 2 | part 3 |', '|---|---|---|---|', ...summary.map(r => '| ' + r.join(' | ') + ' |'), '', '## What is missing', '', ...details);
console.log(out.join('\n'));
